import{_ as o,o as s,c as t,a5 as a}from"./chunks/framework.CsGesDJn.js";const w=JSON.parse('{"title":"3.2.5 Change Password","description":"","frontmatter":{},"headers":[],"relativePath":"feature/authentication/3-2-5-change-password/spec.md","filePath":"feature/authentication/3-2-5-change-password/spec.md"}'),r={name:"feature/authentication/3-2-5-change-password/spec.md"};function d(n,e,i,c,h,l){return s(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="_3-2-5-change-password" tabindex="-1">3.2.5 Change Password <a class="header-anchor" href="#_3-2-5-change-password" aria-label="Permalink to &quot;3.2.5 Change Password&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>FR Code</td><td>3.2.5</td></tr><tr><td>Feature</td><td>Change Password</td></tr><tr><td>Domain</td><td>Authentication (FR 3.2)</td></tr><tr><td>Role</td><td>Any signed-in user, changing their own password</td></tr><tr><td>Version</td><td>1.1 — 2026-09-25 — corrected success toast MSG code (see BA conflict below); confirmed against <code>AuthController</code>/<code>AuthServiceImpl</code></td></tr><tr><td>Document status</td><td>Implemented</td></tr></tbody></table><h2 id="function-trigger" tabindex="-1">Function Trigger <a class="header-anchor" href="#function-trigger" aria-label="Permalink to &quot;Function Trigger&quot;">​</a></h2><p>Begins when a signed-in user opens the change-password section under <code>/settings</code> (Security tab) and submits the current password together with a new password and its confirmation.</p><h2 id="function-description" tabindex="-1">Function Description <a class="header-anchor" href="#function-description" aria-label="Permalink to &quot;Function Description&quot;">​</a></h2><ul><li><strong>Actors / Roles:</strong> Any authenticated user (USER) changing their own password. Applies to any account that already has a password set.</li><li><strong>Purpose:</strong> Let a signed-in user change the password after proving knowledge of the current one, without ending the current session.</li><li><strong>Interface:</strong> A form on the Settings &gt; Security page with three fields — Current Password, New Password, Confirm New Password — and a submit button.</li><li><strong>Data Processing:</strong> The system identifies the caller from the <code>Authorization: Bearer</code> access token, verifies the current password against the stored hash, refuses a new password identical to the current one, replaces the password hash, updates the last-password-change timestamp, and records an audit log event.</li></ul><p><strong>Related/adjacent endpoint:</strong> <code>POST /api/v1/auth/set-password</code> (<code>SetPasswordRequest{password}</code>) covers a different case — an OAuth-only account that has no password yet — and takes only a new password (no current password to verify). It is implemented in the same <code>AuthController</code>/<code>AuthServiceImpl</code> and is documented here only as context; its full behavior belongs to its own FR, not 3.2.5. It requires the same Bearer auth (<code>requireUserId</code> helper) and returns 400 <code>PASSWORD_ALREADY_SET</code> if the account already has a password hash.</p><p><strong>Out of scope:</strong> Forgot/reset password (<code>POST /forgot-password</code>, <code>POST /reset-password</code>) is a separate flow — FR 3.2.4 — and is not covered here.</p><h2 id="screen-layout" tabindex="-1">Screen Layout <a class="header-anchor" href="#screen-layout" aria-label="Permalink to &quot;Screen Layout&quot;">​</a></h2><p>Figure — Change Password (Settings &gt; Security):</p><ul><li>A card titled &quot;Change Password&quot; inside the Settings &gt; Security tab (<code>/settings</code>, Security section).</li><li>Three password inputs, top to bottom: Current Password, New Password, Confirm New Password (client-only confirmation field, not sent to the API).</li><li>A single submit button (&quot;Change Password&quot; / arrow icon) that shows a loading state while the request is in flight.</li><li>On success: a toast confirms the change and the user is navigated to the dashboard; the current session stays signed in.</li><li>On failure: an inline/toast error message is shown and the form remains filled in for correction.</li></ul><p>(Ground truth: <code>brandhub-web-dashboard/src/pages/change-password/index.tsx</code>, calling <code>authService.changePassword({ currentPassword, newPassword })</code> from <code>src/services/authService.ts</code>.)</p><h2 id="function-details" tabindex="-1">Function Details <a class="header-anchor" href="#function-details" aria-label="Permalink to &quot;Function Details&quot;">​</a></h2><h3 id="data-specifications" tabindex="-1">Data Specifications <a class="header-anchor" href="#data-specifications" aria-label="Permalink to &quot;Data Specifications&quot;">​</a></h3><ul><li><strong>Input required:</strong> <code>currentPassword</code>, <code>newPassword</code> (request body <code>ChangePasswordRequest</code>); <code>Authorization: Bearer &lt;accessToken&gt;</code> header.</li><li><strong>Input optional:</strong> <code>confirmNewPassword</code> — client-side only, never sent to the API; checked for equality with <code>newPassword</code> before submit.</li><li><strong>System data:</strong> <code>userId</code> (parsed from the access token&#39;s JWT subject), <code>user.passwordHash</code>, <code>user.lastPasswordChange</code>, the audit log entry.</li><li><strong>Output:</strong> <code>ApiResponse&lt;Void&gt;</code>, HTTP 200, no data payload.</li></ul><h3 id="business-rules" tabindex="-1">Business Rules <a class="header-anchor" href="#business-rules" aria-label="Permalink to &quot;Business Rules&quot;">​</a></h3><ul><li><strong>BR-02:</strong> Password policy — minimum 8 characters and at least 1 digit; the accepted password is hashed with BCrypt at cost factor 12; the password value is never logged or returned in any response.</li><li>Check order in <code>AuthServiceImpl.changePassword</code>: (1) verify <code>currentPassword</code> against <code>user.passwordHash</code> — mismatch → 400 <code>WRONG_CURRENT_PASSWORD</code>; (2) only once (1) passes, compare <code>newPassword</code> against the same stored hash — a match → 400 <code>SAME_AS_CURRENT_PASSWORD</code>; (3) only then hash and persist the new password.</li><li><strong>BR-12:</strong> Changing the password sets <code>lastPasswordChange = now()</code>. A refresh token whose <code>jti</code> was issued before this timestamp is rejected on its next use (<code>REFRESH_TOKEN_INVALID</code>) — i.e., changing the password invalidates every outstanding refresh token, on every device, even though the current access token and current session remain valid until it expires.</li><li>The same <code>AuditAction.PASSWORD_RESET</code> audit action is reused for both Reset Password (3.2.4) and Change Password — the code does not have a distinct &quot;password changed&quot; audit action.</li></ul><h3 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h3><ul><li><code>currentPassword</code> or <code>newPassword</code> empty → Display: MSG02.</li><li><code>newPassword</code> fewer than 8 characters or missing a digit (BR-02) → 400 <code>VALIDATION_ERROR</code>, Display: MSG05.</li><li><code>confirmNewPassword</code> does not match <code>newPassword</code> (client-side only) → Display: MSG06.</li><li>Missing or malformed <code>Authorization: Bearer</code> header → 401 <code>INVALID_CREDENTIALS</code> (checked in <code>AuthController.changePassword</code> before the service is called).</li></ul><h2 id="functionalities" tabindex="-1">Functionalities <a class="header-anchor" href="#functionalities" aria-label="Permalink to &quot;Functionalities&quot;">​</a></h2><h3 id="normal-flow" tabindex="-1">Normal Flow <a class="header-anchor" href="#normal-flow" aria-label="Permalink to &quot;Normal Flow&quot;">​</a></h3><ol><li>The user opens Settings &gt; Security and enters the current password, the new password, and the confirmation.</li><li>The client checks that the confirmation matches the new password; on submit it calls <code>POST /api/v1/auth/change-password</code> with <code>{currentPassword, newPassword}</code> and the Bearer access token.</li><li>The system parses the access token&#39;s JWT subject to resolve the caller&#39;s <code>userId</code> and loads the account.</li><li>The system verifies <code>currentPassword</code> against the stored <code>passwordHash</code>.</li><li>The system compares <code>newPassword</code> against the same stored hash and rejects it if identical.</li><li>The system replaces <code>passwordHash</code> with the BCrypt hash of <code>newPassword</code>, sets <code>lastPasswordChange = now()</code>, saves the user, and writes an audit log entry (<code>AuditAction.PASSWORD_RESET</code>).</li><li>The system returns 200 with no data. The client shows a success toast and navigates to the dashboard; the current session stays signed in, while every outstanding refresh token is invalidated (BR-12).</li></ol><h3 id="abnormal-cases" tabindex="-1">Abnormal Cases <a class="header-anchor" href="#abnormal-cases" aria-label="Permalink to &quot;Abnormal Cases&quot;">​</a></h3><ul><li>2.a1: Missing or malformed <code>Authorization: Bearer</code> header → 401 <code>INVALID_CREDENTIALS</code>. 2.a2: The user is signed out and returned to login.</li><li>3.a1: The account referenced by the token no longer exists → 404 <code>USER_NOT_FOUND</code>. 3.a2: The user is signed out and must sign in again with a valid account.</li><li>4.a1: <code>currentPassword</code> does not match the stored hash (BR-02 check order, evaluated first) → 400 <code>WRONG_CURRENT_PASSWORD</code>, Display: MSG19 (&quot;Current password is incorrect.&quot;). 4.a2: The user re-enters the current password.</li><li>5.a1: <code>newPassword</code> is identical to <code>currentPassword</code>, evaluated only after step 4 has passed → 400 <code>SAME_AS_CURRENT_PASSWORD</code>. 5.a2: The user enters a different new password.</li><li>1.a1: <code>newPassword</code> fails the policy check (BR-02) → 400 <code>VALIDATION_ERROR</code>, Display: MSG05. 1.a2: The user corrects the password and resubmits.</li><li>1.b1: <code>currentPassword</code> or <code>newPassword</code> empty → Display: MSG02. 1.b2: The user fills in the missing field and resubmits.</li><li>Both <code>currentPassword</code> is wrong and <code>newPassword</code> happens to equal the real current password → <code>WRONG_CURRENT_PASSWORD</code> is returned (check order puts it first), never <code>SAME_AS_CURRENT_PASSWORD</code>.</li></ul><h2 id="post-conditions" tabindex="-1">Post-Conditions <a class="header-anchor" href="#post-conditions" aria-label="Permalink to &quot;Post-Conditions&quot;">​</a></h2><ul><li><code>user.passwordHash</code> is replaced with the new BCrypt hash and <code>user.lastPasswordChange</code> is updated to the change time.</li><li>An audit log entry (<code>AuditAction.PASSWORD_RESET</code>) is recorded for the user.</li><li>The current session (current access token) remains valid and signed in.</li><li>Every refresh token issued before the change — on this device or any other — is rejected on its next use (401 <code>REFRESH_TOKEN_INVALID</code>), per BR-12; the user must sign in again on those other sessions.</li></ul><h2 id="out-of-scope" tabindex="-1">Out of Scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of Scope&quot;">​</a></h2><ul><li>Forgot/Reset Password (FR 3.2.4) — the unauthenticated &quot;forgot password&quot; email-token flow. Not covered here.</li><li>Set Password for OAuth-only accounts (<code>POST /api/v1/auth/set-password</code>) — mentioned above as a related endpoint only; its own FR owns the full spec.</li></ul><h2 id="ba-code-conflicts" tabindex="-1">BA / Code Conflicts <a class="header-anchor" href="#ba-code-conflicts" aria-label="Permalink to &quot;BA / Code Conflicts&quot;">​</a></h2><ul><li>⚠ <strong>BA conflict (needs team decision): no dedicated MSG code exists for change-password success.</strong> The BA appendix (<code>Section5_Requirement_Appendix.md</code>) has no MSG entry named for &quot;password changed&quot; — the closest analogous code is <strong>MSG18</strong> (&quot;Password updated successfully.&quot;, currently labelled for Reset Password) and MSG26 is &quot;Profile updated successfully.&quot; (a different feature — profile update, not password). The previous version of this spec cited MSG26, which is incorrect for this flow; this version references <strong>MSG18</strong> as the nearest analogous code pending a BA decision on whether a distinct MSG (e.g. MSG-changepw) should be added.</li></ul><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><p>Ground truth: <code>AuthController.java</code> (<code>changePassword</code>, <code>setPassword</code>, <code>requireUserId</code>), <code>AuthServiceImpl.java</code> (<code>changePassword</code>, <code>setPassword</code>), <code>ErrorCode.java</code>. Frontend: <code>brandhub-web-dashboard/src/pages/change-password/index.tsx</code>, <code>src/services/authService.ts</code>. BA: <code>Section5_Requirement_Appendix.md</code> (BR-02, BR-12, MSG02, MSG05, MSG06, MSG18, MSG19) — read-only, not modified.</p>',32)])])}const p=o(r,[["render",d]]);export{w as __pageData,p as default};
